INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-math210', 'stk-rapls', 'MATH 210', 'doc', '{"docs": [{"id": "stk-dr-m68348", "n": "Dr. Abdallah Laradji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math210-192\n\nالتحضير : يحضر نهاية الكلاس بالSerial number\nطريقة الشرح : يشرح من نوتة هو مسويها مبنية على الكتاب ( المرجع ) , جميلة ومختصرة وفيها أهم التعاريف والشروحات والأمثلة , يشرح منها ع السبورة يكتب كل شي ويشرح ويعلق , ويجاوب ع الأسئلة بأي وقت\nالكويزات : كويزاته جميلة جدًا وأفكارها حلوة تستمتع وأنت تحل , مو صعبة لكن ممكن الوقت م يكفي أحيانًا\nالمياجر: الميجر الأول سهل إلى متوسط , الميجر الثاني لا يوجد بسبب جائحة كورونا\nالفاينلات : أخذت المادة Np فلا أعلم عن الفاينل\nالقريد النهائي: A++++++\nالصوت: واضح لكن هادي\nإضافات : الدكتور ماشاءالله قامة علمية رياضية كبيرة , شرحه ممتع وجميل , بالنسبة للواجبات وصلنا لآخر السمستر ما جا قريدر فما أعرف هل صححها بنفسه أو م حسبها ضمن الدرجات , خلوق جدًا ومتعاون وتصحيحه مقبول إلى حد ما", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522704-math210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-laradji/68348/48", "user": "Rapls", "ts": 1591380246000, "tid": 68348, "pn": 48}}]}', 1591380246000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
